          }
        }
      ]
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/moon_z_fill_1.svg",
      "description": "月亮加Z睡眠实心图标，适合表达宠物睡前仪式和夜间休息状态。"
    }
  ]
}

